begin;set local search_path=public,extensions;select plan(24);
grant usage on schema extensions to authenticated;
grant execute on all functions in schema extensions to authenticated;

select ok((select count(*)=15 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public'and c.relkind='r'and c.relname=any(array['contracts','contract_versions','contract_parties','contract_items','contract_signatures','change_requests','contract_amendments','missions','mission_milestones','service_checklist_templates','mission_checklist_items','deliverables','delivery_versions','delivery_proofs','acceptance_checklists'])),'all contract, amendment, mission, delivery and acceptance tables exist');
select ok((select count(*)=15 and bool_and(c.relrowsecurity)from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public'and c.relname=any(array['contracts','contract_versions','contract_parties','contract_items','contract_signatures','change_requests','contract_amendments','missions','mission_milestones','service_checklist_templates','mission_checklist_items','deliverables','delivery_versions','delivery_proofs','acceptance_checklists'])),'RLS is enabled on every domain table');
select ok((select count(*)=7 and bool_and(p.prosecdef and p.proconfig::text like '%search_path=%')from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname=any(array['generate_contract','submit_contract_for_signature','sign_contract','create_mission','submit_delivery','accept_delivery','create_contract_amendment'])),'seven public commands are security definer with fixed search paths');
select ok(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname=any(array['generate_contract','submit_contract_for_signature','sign_contract','create_mission','submit_delivery','accept_delivery','create_contract_amendment'])and(has_function_privilege('anon',p.oid,'EXECUTE')or has_function_privilege('service_role',p.oid,'EXECUTE'))),'anonymous and service roles cannot execute user commands');
select ok((select count(*)=7 and bool_and(has_function_privilege('authenticated',p.oid,'EXECUTE'))from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname=any(array['generate_contract','submit_contract_for_signature','sign_contract','create_mission','submit_delivery','accept_delivery','create_contract_amendment'])),'authenticated has explicit command execution only');
select ok(not has_table_privilege('authenticated','public.contracts','INSERT')and not has_table_privilege('authenticated','public.contract_versions','UPDATE')and not has_table_privilege('authenticated','public.contract_signatures','INSERT'),'direct contract and signature mutation is denied');
select ok(not has_table_privilege('authenticated','public.missions','UPDATE')and not has_table_privilege('authenticated','public.delivery_versions','INSERT')and not has_table_privilege('authenticated','public.acceptance_checklists','UPDATE'),'direct mission, delivery and acceptance mutation is denied');
select ok((select data_type='bigint'from information_schema.columns where table_schema='public'and table_name='contract_versions'and column_name='price_minor'),'contract money uses bigint minor units, never float');
select ok((select count(*)=1 from pg_constraint where conrelid='public.contract_versions'::regclass and contype='f'and pg_get_constraintdef(oid)like'%selected_quote_version_id%'),'contract version references an exact quote version');
select ok((select count(*)=1 from pg_trigger where tgrelid='public.contract_versions'::regclass and tgname='contract_versions_bind_selected_quote'and not tgisinternal),'selected quote binding is enforced by a server trigger');
select ok((select count(*)>=7 from pg_trigger where tgname=any(array['contract_versions_immutable','contract_parties_immutable','contract_items_immutable','contract_signatures_immutable','amendments_immutable','delivery_versions_immutable','delivery_proofs_immutable'])and not tgisinternal),'signed/versioned records and delivery evidence have immutability guards');
select ok((select count(*)>=13 from pg_policies where schemaname='public'and tablename=any(array['contracts','contract_versions','contract_parties','contract_items','contract_signatures','change_requests','contract_amendments','missions','mission_milestones','mission_checklist_items','deliverables','delivery_versions','delivery_proofs','acceptance_checklists'])),'tenant read policies cover the contract and mission graph');
select ok((select count(*)=2 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private'and p.proname in('contract_party_access','mission_party_access')and p.prosecdef),'tenant access is centralized in protected security-definer predicates');
select ok((select count(*)=2 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private'and p.proname in('begin_contract_command','finish_contract_command')and p.prosecdef),'idempotency command lifecycle is server-controlled');
select ok((select pg_get_functiondef(p.oid)like'%IDEMPOTENCY_PAYLOAD_MISMATCH%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private'and p.proname='begin_contract_command'),'idempotency rejects reuse with a different canonical payload');
select ok((select pg_get_functiondef(p.oid)like'%ContractSignedV1%'and pg_get_functiondef(p.oid)like'%contract.signed%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='sign_contract'),'signature command emits audit and Outbox records');
select ok((select pg_get_functiondef(p.oid)like'%DELIVERY_PROOF_REQUIRED%'and pg_get_functiondef(p.oid)like'%DeliverySubmittedV1%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='submit_delivery'),'delivery command blocks missing proof and emits an Outbox event');
select ok((select pg_get_functiondef(p.oid)like'%ACCEPTANCE_INCOMPLETE%'and pg_get_functiondef(p.oid)like'%NONCOMPLIANT%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='accept_delivery'),'acceptance is criterion-based and cannot silently complete');
select ok((select pg_get_functiondef(p.oid)like'%base_contract_version_id%'and pg_get_functiondef(p.oid)like'%CONTRACT_AMENDMENT_DRAFTED%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='create_contract_amendment'),'amendments preserve the initial contract version and are separately identified');

insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)values
('fc100000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','p08-client@example.invalid','',now(),'{}','{}',now(),now()),
('fc100000-0000-0000-0000-000000000002','00000000-0000-0000-0000-000000000000','authenticated','authenticated','p08-provider@example.invalid','',now(),'{}','{}',now(),now()),
('fc100000-0000-0000-0000-000000000003','00000000-0000-0000-0000-000000000000','authenticated','authenticated','p08-outsider@example.invalid','',now(),'{}','{}',now(),now());
insert into public.organizations(id,legal_name,display_name,status,created_by)values
('fc110000-0000-0000-0000-000000000001','P08 Client','P08 Client','ACTIVE','fc100000-0000-0000-0000-000000000001'),
('fc110000-0000-0000-0000-000000000002','P08 Provider','P08 Provider','ACTIVE','fc100000-0000-0000-0000-000000000002'),
('fc110000-0000-0000-0000-000000000003','P08 Outsider','P08 Outsider','ACTIVE','fc100000-0000-0000-0000-000000000003');
insert into public.organization_memberships(id,organization_id,user_id,status)values
('fc120000-0000-0000-0000-000000000001','fc110000-0000-0000-0000-000000000001','fc100000-0000-0000-0000-000000000001','ACTIVE'),
('fc120000-0000-0000-0000-000000000002','fc110000-0000-0000-0000-000000000002','fc100000-0000-0000-0000-000000000002','ACTIVE'),
('fc120000-0000-0000-0000-000000000003','fc110000-0000-0000-0000-000000000003','fc100000-0000-0000-0000-000000000003','ACTIVE');
insert into public.organization_member_roles(membership_id,role_code)values('fc120000-0000-0000-0000-000000000001','CLIENT_OWNER'),('fc120000-0000-0000-0000-000000000002','PROVIDER_OWNER'),('fc120000-0000-0000-0000-000000000003','CLIENT_OWNER');
insert into public.contracts(id,client_organization_id,provider_organization_id,created_by)values('fc130000-0000-0000-0000-000000000001','fc110000-0000-0000-0000-000000000001','fc110000-0000-0000-0000-000000000002','fc100000-0000-0000-0000-000000000001');

set local role authenticated;select set_config('request.jwt.claims','{"sub":"fc100000-0000-0000-0000-000000000001","role":"authenticated","aal":"aal2"}',true);
select is((select count(*)::integer from public.contracts),1,'client party can read its contract');
select throws_ok($$insert into public.contracts(client_organization_id,provider_organization_id,created_by)values('fc110000-0000-0000-0000-000000000001','fc110000-0000-0000-0000-000000000002','fc100000-0000-0000-0000-000000000001')$$,'42501'::char(5),'permission denied for table contracts','authenticated cannot bypass the command API');
select throws_ok($$select public.generate_contract('fc110000-0000-0000-0000-000000000001','fc110000-0000-0000-0000-000000000002','{}','{}','{}',10,'bad','{}','{}','{}','Invalid currency','p08-invalid-contract')$$,'22023'::char(5),'INVALID_CONTRACT','contract command rejects invalid exact-money currency input');
select set_config('request.jwt.claims','{"sub":"fc100000-0000-0000-0000-000000000003","role":"authenticated","aal":"aal2"}',true);
select is((select count(*)::integer from public.contracts),0,'unrelated tenant cannot read another organization contract');
select throws_ok($$select public.generate_contract('fc110000-0000-0000-0000-000000000001','fc110000-0000-0000-0000-000000000002','{}','{}','{}',10,'MAD','{}','{}','{}','Forbidden contract','p08-forbidden-contract')$$,'42501'::char(5),'CONTRACT_GENERATE_DENIED','unrelated tenant cannot generate a contract for another client');

reset role;select * from finish();rollback;
